class Solution {
public:
    int countVowelPermutation(int n) {
        const int MOD = 1e9 + 7;
        vector<long> a(5, 1);
        for (int i = 1; i < n; ++i) {
            vector<long> b(5);
            b[0] = (a[1] + a[2] + a[4]) % MOD; // 'a'
            b[1] = (a[0] + a[2]) % MOD;         // 'e'
            b[2] = (a[1] + a[3]) % MOD;         // 'i'
            b[3] = a[2];                        // 'o'
            b[4] = (a[2] + a[3]) % MOD;         // 'u'
            a = b;
        }
        return accumulate(a.begin(), a.end(), 0L) % MOD;
    }
};
